// FileServer is the server API for File service.
// All implementations must embed UnimplementedFileServer
// for forward compatibility.
//
// 文件服务定义
type FileServer interface {
	// ===== 基础操作 =====
	// 获取文件信息
	GetFileInfo(context.Context, *FileInfoRequest) (*Response, error)
	// 上传文件
	UploadFile(context.Context, *UploadFileRequest) (*Response, error)
	// 获取用户所有文件列表
	GetFileList(context.Context, *FileListRequest) (*Response, error)
	// 获取用户对应桶文件列表
	GetBucketFileList(context.Context, *BucketFileListRequest) (*Response, error)
	// 重命名文件
	RenameFile(context.Context, *RenameFileRequest) (*Response, error)
	// 删除文件
	DeleteFile(context.Context, *DeleteFileRequest) (*Response, error)
	// 下载文件
	DownloadFile(context.Context, *DownloadFileRequest) (*Response, error)
	// 复制文件
	CopyFile(context.Context, *CopyFileRequest) (*Response, error)
	// ===== 分片上传 =====
	// 初始化分片上传
	InitMultipartUpload(context.Context, *InitMultipartUploadRequest) (*Response, error)
	// 上传单个分片
	UploadPart(context.Context, *UploadPartRequest) (*Response, error)
	// 完成分片上传（合并）
	CompleteMultipartUpload(context.Context, *CompleteMultipartUploadRequest) (*Response, error)
	// 取消分片上传
	AbortMultipartUpload(context.Context, *AbortMultipartUploadRequest) (*Response, error)
	// ===== 文件分享 =====
	// 创建分享
	CreateShare(context.Context, *CreateShareRequest) (*Response, error)
	// 访问分享（匿名）
	AccessShare(context.Context, *AccessShareRequest) (*Response, error)
	// 分享下载（匿名）
	DownloadByShare(context.Context, *DownloadByShareRequest) (*Response, error)
	// 用量统计（需登录）
	GetStorageStats(context.Context, *GetStorageStatsRequest) (*Response, error)
	// 获取预签名下载 URL（需登录；本地驱动不支持返回 40005）
	GetPresignedURL(context.Context, *GetPresignedURLRequest) (*Response, error)
	// 我的分享列表（需登录）
	GetMyShares(context.Context, *GetMySharesRequest) (*Response, error)
	// 撤销分享（需登录，仅限本人分享）
	RevokeShare(context.Context, *RevokeShareRequest) (*Response, error)
	// 流式下载（server-streaming 分块传输，需登录）
	DownloadStream(*DownloadFileRequest, grpc.ServerStreamingServer[DownloadChunk]) error
	// 图片缩略图（需登录；仅本地驱动生成）
	GetFileThumb(context.Context, *FileThumbRequest) (*Response, error)
	// 用量趋势（需登录）
	GetStorageTrend(context.Context, *GetStorageTrendRequest) (*Response, error)
	// 回收站：已删文件列表（需登录）
	ListDeletedFiles(context.Context, *ListDeletedFilesRequest) (*Response, error)
	// 回收站：恢复（需登录，仅限本人）
	RestoreFiles(context.Context, *RestoreFilesRequest) (*Response, error)
	// 回收站：彻底删除（需登录，仅限本人；级联分享/归还配额/删物理文件）
	PurgeFiles(context.Context, *PurgeFilesRequest) (*Response, error)
	// 分享访问审计查询（需登录，仅限本人分享）
	GetShareAccessLogs(context.Context, *GetShareAccessLogsRequest) (*Response, error)
	mustEmbedUnimplementedFileServer()
}

